/*
 * Logo uploads for companies and parties.
 *
 * - Only PNG / JPEG / WebP images up to 2 MB are accepted.
 * - Stored names are generated by the server; the uploaded file name is never used as a path.
 */
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const multer = require("multer");
const { app } = require("electron");

const UPLOAD_ROOT = app.isPackaged
    ? path.join(app.getPath("userData"), "uploads")
    : path.join(__dirname, "../../uploads");

const TEMP_DIR = path.join(UPLOAD_ROOT, "main");
if (!fs.existsSync(TEMP_DIR)) fs.mkdirSync(TEMP_DIR, { recursive: true });

const IMAGE_TYPES = { "image/png": ".png", "image/jpeg": ".jpg", "image/webp": ".webp" };
const MAX_LOGO_BYTES = 2 * 1024 * 1024;

const logoUpload = multer({
    dest: TEMP_DIR,
    limits: { fileSize: MAX_LOGO_BYTES, files: 1 },
    fileFilter: (req, file, cb) => {
        if (IMAGE_TYPES[file.mimetype]) return cb(null, true);
        const error = new Error("Logo must be a PNG, JPG or WebP image.");
        error.status = 400;
        return cb(error);
    },
});

const folderFor = (kind) => {
    const dir = path.join(UPLOAD_ROOT, kind);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    return dir;
};

/** Moves an uploaded logo into uploads/<kind>/ and returns its new file name. */
const saveLogo = (file, kind) => {
    if (!file) return "";
    const ext = IMAGE_TYPES[file.mimetype] || ".png";
    const fileName = `${Date.now()}_${crypto.randomBytes(6).toString("hex")}${ext}`;
    fs.renameSync(file.path, path.join(folderFor(kind), fileName));
    return fileName;
};

/** Deletes a stored logo (ignores names that could point outside the folder). */
const removeLogo = (fileName, kind) => {
    if (!fileName || path.basename(fileName) !== fileName) return;
    fs.unlink(path.join(folderFor(kind), fileName), () => { });
};

/** Drops the temp file of an upload that was rejected after multer accepted it. */
const discardUpload = (file) => {
    if (file?.path) fs.unlink(file.path, () => { });
};

module.exports = { UPLOAD_ROOT, logoUpload, saveLogo, removeLogo, discardUpload };
